def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)

    if not alive_opps:
        if hp <= 2 or no_water >= 2:
            return float(min(budget, DAILY_SALARY * 0.85))
        return float(min(budget, DAILY_SALARY * 0.25))

    prev_bids = []
    desperate_count = 0
    rich_aggressive = 0
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
            desperate_count += 1
        if opp.get('budget', 0) > 400 and bid is not None and bid >= 90:
            rich_aggressive += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    units = supply / WATER_REQ
    can_cover_two = units >= 2.0
    scarce = supply < WATER_REQ * 1.5

    if hp <= 2 or no_water >= 2:
        bid = max(DAILY_SALARY * 0.95, highest_prev + 3.0)
        return float(min(budget, bid))

    if hp <= 4 or no_water >= 1:
        if scarce:
            bid = max(DAILY_SALARY * 0.82, highest_prev + 2.0)
        else:
            bid = max(DAILY_SALARY * 0.68, avg_prev + 1.5)
        return float(min(budget, bid))

    if can_cover_two:
        bid = DAILY_SALARY * 0.34
        if highest_prev > 95:
            bid = DAILY_SALARY * 0.22
        elif highest_prev > 70:
            bid = DAILY_SALARY * 0.28
        elif desperate_count >= 2:
            bid = DAILY_SALARY * 0.42
        return float(min(budget, bid))

    bid = DAILY_SALARY * 0.52
    if scarce:
        bid = max(bid, avg_prev + 1.0)
    if rich_aggressive >= 1:
        bid = min(bid, DAILY_SALARY * 0.48)
    if day >= 8 and hp >= 6:
        bid = min(bid, DAILY_SALARY * 0.40)

    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive'):
            alive.append((oid, o))

    if not alive:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from each opponent's previous_trace
    prev_bids = []
    for oid, o in alive:
        prev = o.get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate how many allocation units are likely available today
    # (allocation model unknown; we use supply to modulate aggressiveness)
    supply_bucket = None
    if supply <= (MIN_SUPPLY + MAX_SUPPLY) / 2:
        supply_bucket = 'low'
    else:
        supply_bucket = 'high'

    # Base bid: try to secure water without overpaying against aggressive Cindy-like behavior
    # If someone previously bid very high, reduce relative to them.
    if highest_prev_bid >= DAILY_SALARY * 1.4:  # ~126+
        base = DAILY_SALARY * 0.45
    elif highest_prev_bid >= DAILY_SALARY * 0.9:  # ~81+
        base = DAILY_SALARY * 0.55
    else:
        base = DAILY_SALARY * 0.62

    # Adjust for my health pressure
    if my_hp <= 2.0 or my_no_water_days >= 2:
        base = DAILY_SALARY * 0.85
    elif my_hp <= 4.0:
        base = DAILY_SALARY * 0.70

    # Adjust for supply regime
    if supply_bucket == 'low':
        base *= 0.90
    else:
        base *= 1.00

    # Ensure we don't bid more than we can afford
    bid = min(my_budget, base)

    # If my budget is extremely low, bid whatever is left (can't do better)
    if my_budget <= DAILY_SALARY * 0.15:
        bid = my_budget

    # Clamp to [0, budget]
    if bid < 0.0:
        bid = 0.0
    if bid > my_budget:
        bid = my_budget

    return float(bid)

